#include <linux/uaccess.h>
#include <linux/socket.h>
#include <linux/sockios.h>

int sendto(int fd, void __user *buff, size_t len, unsigned int flags,
           struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret;

    if (!buff || len == 0)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    memset(&msg, 0, sizeof(msg));
    msg.msg_name = NULL;
    msg.msg_namelen = 0;
    msg.msg_flags = flags;

    if (addr) {
        struct sockaddr *kaddr;

        kaddr = kmalloc(addr_len, GFP_KERNEL);
        if (!kaddr) {
            ret = -ENOMEM;
            goto out;
        }
        if (copy_from_user(kaddr, addr, addr_len)) {
            ret = -EFAULT;
            kfree(kaddr);
            goto out;
        }
        msg.msg_name = kaddr;
        msg.msg_namelen = addr_len;
    }

    msg.msg_iov = NULL;
    msg.msg_iovlen = 0;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;

    if (sock->file->f_flags & O_NONBLOCK)
        msg.msg_flags |= MSG_DONTWAIT;

    ret = sock_sendmsg(sock, &msg, len);
    if (ret < 0)
        goto out;

out:
    if (addr && msg.msg_name)
        kfree(msg.msg_name);
    sockfd_put(sock);
    return ret;
}

int sys_sendto(int fd, void __user *buff, size_t len, unsigned int flags,
               struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret;

    if (len == 0)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    ret = -EFAULT;
    if (buff) {
        if (verify_area(VERIFY_READ, buff, len))
            goto out_put;
    }

    memset(&msg, 0, sizeof(msg));
    msg.msg_name = addr;
    msg.msg_namelen = addr_len;
    msg.msg_iov = &msg.msg_iter.iov;
    msg.msg_iter.iov = (struct iovec) { .iov_base = buff, .iov_len = len };
    msg.msg_iter.count = len;
    msg.msg_flags = flags;

    if ((sock->flags & SOCK_NONBLOCK) || (flags & MSG_DONTWAIT))
        msg.msg_flags |= MSG_DONTWAIT;

    ret = sock_sendmsg(sock, &msg, len);

out_put:
    sockfd_put(sock);
    return ret;
}

#include <linux/uaccess.h>
