#include <linux/socket.h>
#include <linux/uaccess.h>
#include <linux/sockios.h>
#include <linux/fdtable.h>

int sendto(int fd, void __user *buff, size_t len, unsigned int flags,
           struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret;

    if (len > INT_MAX)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    ret = -EFAULT;

    if (buff) {
        if (copy_from_user(&msg, &msg, sizeof(msg)))
            goto out;
        msg.msg_name = NULL;
        msg.msg_namelen = 0;
        if (addr) {
            struct sockaddr kernel_addr;
            if (addr_len > sizeof(kernel_addr))
                goto out;
            if (copy_from_user(&kernel_addr, addr, addr_len))
                goto out;
            msg.msg_name = &kernel_addr;
            msg.msg_namelen = addr_len;
        }
        msg.msg_control = NULL;
        msg.msg_controllen = 0;
        msg.msg_flags = flags;
        if (sock->file->f_flags & O_NONBLOCK)
            msg.msg_flags |= MSG_DONTWAIT;
        ret = sock_sendmsg(sock, &msg, len);
    } else {
        ret = -EFAULT;
    }

out:
    sockfd_put(sock);
    return ret;
}

#include <linux/socket.h>
#include <linux/uaccess.h>
#include <linux/sockios.h>
#include <linux/fdtable.h>
#include <linux/fs.h>
#include <linux/file.h>
#include <asm/unistd.h>

int sendto(int fd, void __user *buff, size_t len, unsigned int flags,
           struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret;
    int nonblocking;

    if (len == 0) {
        return 0;
    }

    if (buff == NULL) {
        return -EFAULT;
    }

    sock = sockfd_lookup(fd, &ret);
    if (!sock) {
        return ret;
    }

    nonblocking = (flags & O_NONBLOCK);

    msg.msg_name = NULL;
    msg.msg_namelen = 0;
    msg.msg_iov = NULL;
    msg.msg_iovlen = 0;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = 0;

    if (addr) {
        msg.msg_name = kmalloc(addr_len, GFP_KERNEL);
        if (!msg.msg_name) {
            ret = -ENOMEM;
            goto out;
        }

        if (copy_from_user(msg.msg_name, addr, addr_len)) {
            ret = -EFAULT;
            kfree(msg.msg_name);
            goto out;
        }

        msg.msg_namelen = addr_len;
    }

    msg.msg_flags = nonblocking ? MSG_DONTWAIT : 0;

    ret = sock_sendmsg(sock, &msg, len);

    if (msg.msg_name) {
        kfree(msg.msg_name);
    }

out:
    sockfd_put(sock);
    return ret;
}
